package com.kovian.finance.card.repository; import com.kovian.finance.card.domain.CreditCardInvoice; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*; public interface CreditCardInvoiceRepository extends JpaRepository<CreditCardInvoice,UUID>{Optional<CreditCardInvoice> findByCardIdAndReferenceMonth(UUID c,LocalDate m);List<CreditCardInvoice> findByOwnerIdOrderByDueDate(UUID o);Optional<CreditCardInvoice> findByIdAndOwnerId(UUID id,UUID o);@Query("select i from CreditCardInvoice i where i.dueDate between :from and :to and i.status <> com.kovian.finance.card.domain.InvoiceStatus.PAID order by i.dueDate asc") List<CreditCardInvoice> findDueBetween(@Param("from")LocalDate from,@Param("to")LocalDate to);}